from pathlib import Path
import sys,unittest,copy
B=Path(__file__).resolve().parent.parent;sys.path.insert(0,str(B/'coordinate-independent-20261016'))
from xy_decode import decode
from agreement_probe import dominant_guard,resolve_digits

def fixture():
    out=[];x=36.
    for c in '14,34,0':
        width=20. if c.isdigit() else 8.
        out.append({'char':c,'score':.98,'xyxy':[x,3.,x+width,39.]});x+=width+2.
    return out

class AgreementProbeTests(unittest.TestCase):
    def test_weak_secondary_alternative_does_not_veto_dominant_agreement(self):
        raw=fixture();other=copy.deepcopy(raw);other.append({**raw[1],'char':'3','score':.27})
        selected=decode(raw)['selected'];self.assertIsNotNone(dominant_guard(selected,{'raw':raw,'contrast':other})[0])

    def test_close_secondary_alternative_still_rejects(self):
        raw=fixture();other=copy.deepcopy(raw);other.append({**raw[1],'char':'3','score':.6})
        self.assertIsNone(dominant_guard(decode(raw)['selected'],{'raw':raw,'contrast':other})[0])

    def test_missing_secondary_digit_is_not_guessed(self):
        raw=fixture();self.assertIsNone(dominant_guard(decode(raw)['selected'],{'raw':raw,'contrast':raw[:1]+raw[2:]})[0])

    def test_second_route_disagreement_still_rejects(self):
        raw=fixture();other=copy.deepcopy(raw);other[1]['char']='7'
        self.assertIsNone(dominant_guard(decode(raw)['selected'],{'raw':raw,'contrast':other})[0])

    def test_clear_digit_overlap_requires_matching_dominant_secondary(self):
        raw=fixture();raw.append({**raw[1],'char':'3','score':.27});self.assertIsNone(decode(raw)['selected'])
        repaired,resolutions=resolve_digits(raw,fixture());selected=decode(repaired)['selected'];self.assertIsNotNone(selected);self.assertEqual(selected['xy'],[14,34]);self.assertEqual(len(resolutions),1)

    def test_primary_overlap_not_resolved_without_secondary(self):
        raw=fixture();raw.append({**raw[1],'char':'3','score':.27});repaired,_=resolve_digits(raw,[]);self.assertIsNone(decode(repaired)['selected'])

    def test_primary_near_tie_not_resolved(self):
        raw=fixture();raw.append({**raw[1],'char':'3','score':.6});repaired,_=resolve_digits(raw,fixture());self.assertIsNone(decode(repaired)['selected'])

    def test_symbols_are_not_removed_as_digit_alternatives(self):
        raw=fixture();raw.append({**raw[1],'char':'-','score':.27});repaired,_=resolve_digits(raw,fixture());self.assertIsNone(decode(repaired)['selected'])

    def test_optional_z_conflict_does_not_veto_xy(self):
        raw=fixture();other=copy.deepcopy(raw);other.append({**raw[-1],'char':'8','score':.98})
        self.assertEqual(dominant_guard(decode(raw)['selected'],{'raw':raw,'contrast':other})[0]['xy'],[14,34])

    def test_shared_wrong_digit_is_documented_blind_spot(self):
        raw=fixture();raw[1]['char']='7';self.assertEqual(dominant_guard(decode(raw)['selected'],{'raw':raw,'contrast':copy.deepcopy(raw)})[0]['xy'],[17,34])

if __name__=='__main__':unittest.main()

