"""Throwaway offline analysis. No product changes or label-dependent decisions."""
from pathlib import Path
import json, sys, hashlib, collections, statistics
R=Path(__file__).resolve().parent; B=R.parent; T=B/'coordinate-targeted-retrain-20261016'; F=B/'coordinate-independent-20261016'
sys.path.insert(0,str(F))
from xy_decode import decode, _iou, _center
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()

def prefix_digits(obs):
    # Reproduce frozen decoder grouping, then locate its exact selected group.
    d=decode(obs)
    if not d['selected']:return None
    unique=[]
    for o in sorted((o for o in obs if o['score']>=.25),key=lambda o:-o['score']):
        if not any(o['char']==p['char'] and _iou(o['xyxy'],p['xyxy'])>.45 for p in unique):unique.append(o)
    unique.sort(key=_center)
    width=statistics.median(o['xyxy'][2]-o['xyxy'][0] for o in unique if o['char'].isdigit())
    groups=[];right=None
    for o in unique:
        if right is None or o['xyxy'][0]-right>max(12.,.75*width):groups.append([]);right=o['xyxy'][2]
        else:right=max(right,o['xyxy'][2])
        groups[-1].append(o)
    groups=[g for g in groups if ''.join(o['char'] for o in g)==d['selected']['observedGroupText']]
    assert len(groups)==1
    g=groups[0];end=[n for n,o in enumerate(g) if o['char']==','][1]
    return [o for o in g[:end] if o['char'].isdigit()]

def guard(selected,obs,policy):
    if selected is None:return None,[]
    if policy=='unmodified':return selected,[]
    if policy=='xy-score-0.50':return (selected,[]) if selected['xyScore']>=.5 else (None,['low-xy-score'])
    digits=prefix_digits(obs['raw']);assert digits
    reasons=[]
    for o in digits:
        if policy in ['digit-score-0.50','paired-digits-and-score-0.50'] and o['score']<.5:reasons.append('low-digit-score')
        if policy in ['paired-digits-0.25','paired-digits-and-score-0.50']:
            neighbors=[p for p in obs['contrast'] if p['score']>=.25 and _iou(o['xyxy'],p['xyxy'])>=.5]
            if not any(p['char']==o['char'] for p in neighbors):reasons.append('digit-not-confirmed')
            if any(p['char']!=o['char'] for p in neighbors):reasons.append('digit-conflict')
    return (None,sorted(set(reasons))) if reasons else (selected,[])

def grade(truth,selected):
    if truth['state']=='unknown':return 'unknownReturned' if selected else 'unknownNoReturn'
    if truth['state']=='absent':return 'falsePositive' if selected else 'trueNegative'
    return 'miss' if selected is None else 'correct' if selected['xy']==[truth['expected'][k] for k in 'xy'] else 'wrong'

def main():
    sources=[T/'evaluation-pytorch.json',T/'evaluation-refined-pytorch.json',T/'evaluation-expanded-onnx.json',T/'score-final-pytorch.json',T/'evaluation-inputs.json',T/'development-view-v2.json',F/'full-110DF22E/labels-v6-user-confirmed.json',F/'xy_decode.py']
    frozen={str(p):sha(p) for p in sources}
    previous=read(T/'score-final-pytorch.json');truth={r['id']:{'state':r['state'],'expected':r['expected']} for r in previous['rows']}
    groups={r['id']:r['groups'] for r in previous['rows']}
    new={f['id']:f for f in read(F/'full-110DF22E/labels-v6-user-confirmed.json')['frames']}
    view=read(T/'development-view-v2.json');train=set(view['trainingFrames']);purge=set(view['purgedFrames'])
    gpu=read(T/'evaluation-pytorch.json')['trials'];gpu.update(read(T/'evaluation-refined-pytorch.json')['trials'])
    datasets={k:v['rows'] for k,v in gpu.items()};datasets['expanded-onnx']=read(T/'evaluation-expanded-onnx.json')['rows']
    policies=['unmodified','xy-score-0.50','digit-score-0.50','paired-digits-0.25','paired-digits-and-score-0.50']
    counts=collections.defaultdict(collections.Counter);records=[]
    final_index={(r['mode'],r['id']):r for r in previous['rows']}
    for model,rows in datasets.items():
        for r in rows:
            fid=r['id']
            if fid not in truth:
                assert fid.endswith('000835');continue
            f=truth[fid];base=r['pipeline']['selected'];original=grade(f,base)
            assert original==final_index[('expanded' if model=='expanded-onnx' else model,fid)]['outcomeXY']
            gs=[g for g in groups[fid] if g in ['old-development','old-fit-or-historical','new-full-observed']]
            if fid in new:
                gs.append(new[fid]['scene'])
                if new[fid]['frame'] not in train|purge:gs.append('new-39-source-observational')
            for policy in policies:
                selected,reasons=guard(base,r['detections'],policy);outcome=grade(f,selected)
                assert selected is None or selected==base # Guards can only abstain.
                for group in gs:counts[model,policy,group][outcome]+=1
                if reasons:records.append({'model':model,'policy':policy,'id':fid,'groups':gs,'before':original,'after':outcome,'selectedBefore':base,'reasons':reasons})
    summary=[{'model':m,'policy':p,'group':g,**dict(c)} for (m,p,g),c in counts.items()]
    # Independent CPU cached detections must give exactly the same guarded XY.
    ix={r['id']:r for r in datasets['expanded']};agreement=collections.Counter()
    for r in datasets['expanded-onnx']:
        for policy in policies:
            a=guard(r['pipeline']['selected'],r['detections'],policy)[0];p=ix[r['id']];b=guard(p['pipeline']['selected'],p['detections'],policy)[0]
            assert (a['xy'] if a else None)==(b['xy'] if b else None),(policy,r['id'])
            agreement[policy]+=1
    assert all(sha(Path(p))==v for p,v in frozen.items())
    report={'scope':'Throwaway offline diagnostic probe, not product code or independent acceptance. Fixed simple hypotheses: .50 confidence floor and/or .25 same-digit secondary evidence with IoU>=.50. No threshold sweep or per-frame exceptions. Same detector raw/contrast routes are correlated, not independent models. All policies only remove returns. Session has been used for training and analysis.','sourceSHA256':frozen,'policies':policies,'summary':summary,'changed':records,'cpuGpuAgreement':dict(agreement),'productionChanged':False}
    dest=R/'probe-report.json';assert not dest.exists();dest.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    for row in summary:
        if row['model'] in ['expanded','refined'] and row['group'] in ['old-development','new-full-observed','new-39-source-observational']:print(row)
    print('CPU/GPU guarded XY agreement:',dict(agreement))

if __name__=='__main__':main()

